import { ConfigServiceBase } from "./ConfigServiceBase.js";
export class ManualPollConfigService extends ConfigServiceBase {
    constructor(options) {
        super(options);
        this.prepareClientForEvents();
        const initialCacheSyncUp = this.syncUpWithCache();
        this.readyPromise = this.getReadyPromise(initialCacheSyncUp);
    }
    getCacheState(cachedConfig) {
        if (cachedConfig.isEmpty) {
            return 0;
        }
        return 2;
    }
    async getConfigAsync() {
        this.options.logger.debug("ManualPollService.getConfigAsync() called.");
        return await this.syncUpWithCache();
    }
    refreshConfigAsync() {
        this.options.logger.debug("ManualPollService.refreshConfigAsync() called.");
        return super.refreshConfigAsync();
    }
}
